(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.016-t*0.22)*18 + Math.sin(x*0.014+t*0.3)*12;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8;
  const w2y = Math.cos((x-y)*0.012-t*0.2)*8;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [120+Math.sin(t*0.5)*110, 60+Math.cos(t*0.35)*45, 0.075, 2.2, 1.0],
    [360+Math.cos(t*0.45)*100, 60+Math.sin(t*0.6)*40, 0.085, 1.9, 0.9],
    [240+Math.sin(t*0.3+2)*150, 120+Math.cos(t*0.45+1)*100, 0.055, 2.5, 1.1],
    [80+Math.cos(t*0.7+1)*90, 180+Math.sin(t*0.5+3)*70, 0.095, 1.6, 0.85],
    [400+Math.sin(t*0.4+4)*80, 170+Math.cos(t*0.8+2)*60, 0.065, 2.8, 1.05],
    [200+Math.cos(t*0.35+5)*100, 210+Math.sin(t*0.5)*60, 0.08, 2.0, 0.95],
    [300+Math.sin(t*0.55+3)*70, 30+Math.cos(t*0.65)*50, 0.11, 1.4, 0.8],
    [40+Math.sin(t*0.42+1.5)*60, 120+Math.cos(t*0.38+2.5)*80, 0.07, 2.3, 1.0]
  ];
  let aS=0, iS=0, wA=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    aS += wave * w;
    iS += Math.sin(d*f*0.65 + t*sp*0.55 + 1.7) * w;
    wA += w;
  }
  aS /= wA; iS /= wA;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.7) + Math.sin(sx*0.028-sy*0.038+t*0.95))/2;
  const bg2 = Math.sin((sx+sy)*0.11+t*2.2)*0.2 + Math.sin((sx-sy)*0.09-t*1.8)*0.2;
  const bg3 = Math.sin(sx*0.07+t*1.3)*Math.sin(sy*0.065-t*1.1)*0.15;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
