  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.0);
  const sp3 = Math.sin(dist*0.06-ang*2-t*1.8)*0.3;
  const spiral = (sp1+sp2)*0.35 + sp3;
  const cross = Math.sin(sx*0.08+sy*0.05+t*0.6)*Math.cos(sx*0.06-sy*0.09-t*0.8)*0.3;
  const rd1 = Math.tanh((aS - iS*0.65 + bg*0.35 + spiral)*2.0);
  const rd2 = Math.tanh((iS*0.8 - aS*0.4 + bg*0.5 + cross + spiral*0.5)*1.8);
  const cell = Math.tanh((Math.sin(sx*0.16)*Math.sin(sy*0.16) + Math.sin((sx+sy)*0.11+t)*0.45 + Math.sin(sx*0.08-sy*0.08+t*0.7)*0.3)*1.4)*0.25;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.28-t*2.5)*0.08;
  const blend = rd1*0.5 + rd2*0.2 + cell*0.2 + micro;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,48],[10,35,82],[15,68,115],[18,105,135],
    [35,155,145],[120,190,140],[200,195,80],
    [225,160,65],[215,110,60],[180,65,60],[120,30,50],
    [60,15,42],[20,10,45],[5,12,48]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const c0=pal[i], c1=pal[i+1];
  const r = c0[0]+(c1[0]-c0[0])*f, g = c0[1]+(c1[1]-c0[1])*f, b = c0[2]+(c1[2]-c0[2])*f;
  const lum = 0.82 + Math.sin(rd1*Math.PI)*0.18;
