  const glow = Math.max(0, 1-dist/280)*0.08;
  return [
    Math.min(255, (r*lum*edge + glow*40)|0),
    Math.min(255, (g*lum*edge + glow*30)|0),
    Math.min(255, (b*lum*edge + glow*50)|0)
  ];
}
